package com.inventoryitemcounter;

import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemComposition;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

public class InventoryItemCounterOverlay extends WidgetItemOverlay
{
    private final Client client;
    private final InventoryItemCounterPlugin plugin;
    private final ItemManager itemManager;

    private int lastTick = -1;
    private final int[] slotCounts = new int[28];

    @Inject
    public InventoryItemCounterOverlay(Client client, InventoryItemCounterPlugin plugin, ItemManager itemManager)
    {
        this.client = client;
        this.plugin = plugin;
        this.itemManager = itemManager;
        showOnInventory();
    }

    public void invalidateCache()
    {
        this.lastTick = -1;
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
    {
        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        if (inventory == null || widgetItem.getWidget() == null)
        {
            return;
        }

        int targetSlot = widgetItem.getWidget().getIndex();
        if (targetSlot < 0 || targetSlot >= slotCounts.length)
        {
            return;
        }

        int currentTick = client.getTickCount();
        if (currentTick != lastTick)
        {
            calculateSlotCounts(inventory);
            lastTick = currentTick;
        }

        int count = slotCounts[targetSlot];
        if (count <= 0)
        {
            return;
        }

        Rectangle bounds = widgetItem.getCanvasBounds();
        String text = String.valueOf(count);

        FontMetrics fm = graphics.getFontMetrics();
        int x = (int) bounds.getMaxX() - fm.stringWidth(text) - 2;
        int y = (int) bounds.getMaxY() - 2;

        graphics.setFont(FontManager.getRunescapeBoldFont());
        graphics.setColor(Color.BLACK);
        graphics.drawString(text, x + 1, y + 1);

        graphics.setColor(Color.YELLOW);
        graphics.drawString(text, x, y);
    }

    private void calculateSlotCounts(ItemContainer inventory)
    {
        Arrays.fill(slotCounts, 0);
        Item[] items = inventory.getItems();
        Map<String, Integer> runningCounts = new HashMap<>();

        for (int i = 0; i < items.length && i < slotCounts.length; i++)
        {
            Item item = items[i];
            if (item == null || item.getId() <= -1)
            {
                continue;
            }

            ItemComposition comp = itemManager.getItemComposition(item.getId());
            String itemName = comp.getName().toLowerCase();

            if (plugin.getBlacklist().contains(itemName))
            {
                continue;
            }

            if (!plugin.getWhitelist().isEmpty() && !plugin.getWhitelist().contains(itemName))
            {
                continue;
            }

            String countKey = plugin.getMergeMap().getOrDefault(itemName, itemName);

            int currentCount = runningCounts.getOrDefault(countKey, 0) + 1;
            runningCounts.put(countKey, currentCount);
            slotCounts[i] = currentCount;
        }
    }
}

package com.inventoryitemcounter;

import com.google.inject.Provides;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import javax.inject.Inject;
import lombok.Getter;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
		name = "Inventory Item Counter",
		description = "Counts quantity of each item on your inventory. Allows for whitelisting and blacklisting.",
		tags = {"inventory", "counter", "items"}
)
public class InventoryItemCounterPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private InventoryItemCounterOverlay overlay;

	@Inject
	private InventoryItemCounterConfig config;

	@Getter
	private List<String> whitelist = Collections.emptyList();

	@Getter
	private List<String> blacklist = Collections.emptyList();

	@Getter
	private Map<String, String> mergeMap = Collections.emptyMap();

	@Override
	protected void startUp()
	{
		updateParsedLists();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onConfigChanged(ConfigChanged event)
	{
		if (!"inventoryitemcounter".equals(event.getGroup()))
		{
			return;
		}

		updateParsedLists();
	}

	private void updateParsedLists()
	{
		this.whitelist = parseList(config.whitelist());
		this.blacklist = parseList(config.blacklist());
		this.mergeMap = parseMergeMap(config.mergelist());

		if (overlay != null)
		{
			overlay.invalidateCache();
		}
	}

	private List<String> parseList(String input)
	{
		if (input == null || input.trim().isEmpty())
		{
			return Collections.emptyList();
		}
		return Arrays.stream(input.split(","))
				.map(String::trim)
				.map(String::toLowerCase)
				.filter(s -> !s.isEmpty())
				.collect(Collectors.toList());
	}

	private Map<String, String> parseMergeMap(String input)
	{
		if (input == null || input.trim().isEmpty())
		{
			return Collections.emptyMap();
		}

		Map<String, String> map = new HashMap<>();
		Matcher matcher = Pattern.compile("\\[(.*?)]").matcher(input);

		while (matcher.find())
		{
			String groupContent = matcher.group(1);
			String[] items = groupContent.split(",");
			if (items.length == 0)
			{
				continue;
			}

			String canonicalKey = items[0].trim().toLowerCase();
			if (canonicalKey.isEmpty())
			{
				continue;
			}

			for (String item : items)
			{
				String name = item.trim().toLowerCase();
				if (!name.isEmpty())
				{
					map.put(name, canonicalKey);
				}
			}
		}

		return map;
	}

	@Provides
	@SuppressWarnings("unused")
	InventoryItemCounterConfig getConfig(ConfigManager configManager)
	{
		return configManager.getConfig(InventoryItemCounterConfig.class);
	}
}

package com.inventoryitemcounter;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("inventoryitemcounter")
public interface InventoryItemCounterConfig extends Config
{
	@ConfigItem(
			keyName = "whitelist",
			name = "Whitelist",
			description = "Item names that will be counter separated by commas (eg: Raw salmon, Hammer). Empty means everything is counted.",
			position = 1
	)
	default String whitelist()
	{
		return "";
	}

	@ConfigItem(
			keyName = "blacklist",
			name = "Blacklist",
			description = "Item names that will be ignored separated by commas (eg: Raw salmon, Hammer).",
			position = 2
	)
	default String blacklist()
	{
		return "";
	}

	@ConfigItem(
			keyName = "mergelist",
			name = "Merge list",
			description = "Items that will be counted together built in arrays separated by commas (eg: [Raw salmon, Salmon], [Bucket, Bucket of sand]).",
			position = 3
	)
	default String mergelist()
	{
		return "";
	}
}
